import artefact from "./noise-bands.json";

// The calibration artefact (design rev. 4, §3). noise-bands.json is copied as generated by the offline calibration
// (docs/audits/linkedin-games-p1-calibration/p1_artifact.py): never edited by hand and never recalculated here.
export type Band = [lower: number, upper: number];
export interface GameBands { "28": Band; "28v56": Band; rho112: Band }
export interface NoiseBands { calibratedThrough: string; games: Record<string, GameBands> }

const band = (v: unknown, where: string): Band => {
  if (!Array.isArray(v) || v.length !== 2 || !v.every((x) => typeof x === "number" && Number.isFinite(x)) || v[0] >= v[1]) throw new Error(`noise-bands.json: invalid band at ${where}`);
  return [v[0], v[1]];
};

// Maps the artefact's statistic names to the contract's keys and fails loudly if the file is malformed.
export function parseNoiseBands(a: unknown): NoiseBands {
  const x = a as { calibratedThrough?: unknown; games?: Record<string, { limits?: Record<string, unknown> }> };
  if (typeof x?.calibratedThrough !== "string" || !x.games) throw new Error("noise-bands.json: missing calibratedThrough or games");
  const games: Record<string, GameBands> = {};
  for (const [g, v] of Object.entries(x.games)) {
    const l = v.limits ?? {};
    games[g] = { "28": band(l.d28v28, `${g}.d28v28`), "28v56": band(l.d28v56, `${g}.d28v56`), rho112: band(l.rho112, `${g}.rho112`) };
  }
  return { calibratedThrough: x.calibratedThrough, games };
}

export const NOISE_BANDS: NoiseBands = parseNoiseBands(artefact);
